        return hasattr(instance, 'speak')

class Animal(metaclass=VirtualMeta):
    pass

class Dog:
    def speak(self):
        return "Woof"

class Cat:
    def meow(self):
        return "Meow"

print(isinstance(Dog(), Animal))
print(isinstance(Cat(), Animal))

from typing import Concatenate, ParamSpec, Callable

P = ParamSpec('P')

def add_logger(f: Callable[Concatenate[str, P], None]) -> Callable[P, None]:
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> None:
        print("Logging enabled")
        return f("INFO", *args, **kwargs)
    return wrapper

@add_logger
def process(level: str, message: str) -> None:
    print(f"[{level}] {message}")

process("Hello World")

import functools

def decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@decorator
def greet():
    """Say hello."""
    return "Hello"

print(greet.__name__)
print(greet.__doc__)

class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def __format__(self, spec):
        if spec == 'polar':
            import math
            r = math.hypot(self.x, self.y)
            theta = math.atan2(self.y, self.x)
            return f"({r:.2f}, {theta:.2f} rad)"
        return f"({self.x}, {self.y})"

v = Vector(1, 1)
print(f"{v:polar}")

class RangeIterator:
    def __init__(self, stop):
        self.current = 0
        self.stop = stop
    def __iter__(self):
        return self
    def __next__(self):
        if self.current >= self.stop:
            raise StopIteration
        self.current += 1
        return self.current - 1
    def __length_hint__(self):
        return self.stop - self.current

r = RangeIterator(100)
import operator
print(operator.length_hint(r))

from typing import Never

def terminate(message: str) -> Never:
    raise SystemExit(message)

try:
    terminate("Goodbye")
except SystemExit as e:
    print(str(e))

class Dynamic:
    _generated = {}
    def __class_getattr__(cls, name):
        if name.startswith('gen_'):
            value = f"Generated {name[4:]}"
            setattr(cls, name, value)
            return value
        raise AttributeError(name)

print(Dynamic.gen_test)
